const int pin = {{P0}};
int last = -1;

void setup() {
  Serial.begin(9600);
  pinMode(pin, INPUT_PULLUP);
}

void loop() {
  int state = digitalRead(pin);
  if (state != last) {
    delay(25);
    state = digitalRead(pin);
    if (state != last) Serial.println(state == LOW ? "Pressed" : "Released");
    last = state;
  }
  delay(5);
}

